 * License: Open Source (TailwindFlex community)
 */
import React from "react";

export function BoutonsIos26() {
  return (
    <div dangerouslySetInnerHTML={{ __html: "<!DOCTYPE html>
<html lang="en" class="dark">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0"/>
  <title>iOS 26 Buttons — Framework7 Style</title>



  <style>
    body {
      background: #000;
      color: white;
      min-height: 100vh;
      display: flex;
      flex-direction: column;
      align-items: center;
      justify-content: center;
      gap: 2rem;
      padding: 2rem;
    }

    /* === BOUTON IOS 26 PRIMAIRE (Framework7 style) === */
    .ios-btn {
      display: inline-flex;
      align-items: center;
      justify-content: center;
      height: 44px;
      padding: 0 20px;
      font-size: 17px;
      font-weight: 500;
      line-height: 1.4;
      letter-spacing: -0.02em;
      text-align: center;
      text-transform: uppercase;
      border-radius: 12px;
      border: 1px solid transparent;
      background: transparent;
      color:white; 
      cursor: pointer;
      user-select: none;
      transition: all 0.2s ease-out;
      -webkit-tap-highlight-color: transparent;
    }

    /* État normal clair */
    .light .ios-btn {
      color: #007aff;
    }

    /* État normal sombre */
    .dark .ios-btn {
      color: #0a84ff;
    }

    /* Hover / Active */
    .ios-btn:hover,
    .ios-btn:active {
      background: rgba(0, 122, 255, 0.1);
      color:white; 
      transform: scale(0.98);
    }

    .dark .ios-btn:hover,
    .dark .ios-btn:active {
      background: rgba(10, 132, 255, 0.15);
       color:white; 
    }

    /* === BOUTON IOS 26 DÉSTRUCTIF === */
    .ios-btn--destructive {
      color: #ff3b30;
    }

    .light .ios-btn--destructive:hover,
    .light .ios-btn--destructive:active {
      background: rgba(255, 59, 48, 0.1);
    }

    .dark .ios-btn--destructive:hover,
    .dark .ios-btn--destructive:active {
      background: rgba(255, 69, 58, 0.15);
    }

    /* === BOUTON IOS 26 NEUTRE (gris) === */
    .ios-btn--neutral {
      color: #8e8e93;
    }

    .light .ios-btn--neutral:hover,
    .light .ios-btn--neutral:active {
      background: rgba(142, 142, 147, 0.1);
    }

    .dark .ios-btn--neutral:hover,
    .dark .ios-btn--neutral:active {
      background: rgba(142, 142, 147, 0.12);
    }

    /* === BOUTON PLEIN (comme dans les modales) === */
    .ios-btn--fill {
      background: #0a84ff;
      color: white !important;
      border: none;
    }

    .ios-btn--fill:hover,
    .ios-btn--fill:active {
      background: #007aff;
       color:white; 
      transform: scale(0.985);
    }

    /* === Icône (optionnel) === */
    .ios-btn svg {
      margin-left: 6px;
      transition: transform 0.2s ease;
    }

    .ios-btn:hover svg {
      transform: translateX(2px);
    }
  </style>
</head>
<body x-data="{ count: 0 }">
  <h2 class="text-xl font-semibold mb-6">Boutons iOS 26 — Framework7 Style</h2>

  <!-- Bouton standard (lien d'action) -->
  <button 
    class="ios-btn"
    @click="count++"
  >
    Action
  </button>

  <!-- Bouton destructif -->
  <button 
    class="ios-btn ios-btn--destructive"
    @click="count = 0"
  >
    Delete
  </button>

  <!-- Bouton neutre -->
  <button 
    class="ios-btn ios-btn--neutral"
    @click="count--"
  >
    Cancel
  </button>

  <!-- Bouton plein (style modale) -->
  <button 
    class="ios-btn ios-btn--fill"
    style="width: 200px"
    @click="alert('Confirmed!')"
  >
    Confirm
  </button>

  <!-- Bouton avec icône -->
  <button class="ios-btn">
    Next
    <svg width="16" height="16" viewBox="0 0 16 16" fill="none" xmlns="http://www.w3.org/2000/svg">
      <path d="M5.293 3.293a1 1 0 011.414 0l4 4a1 1 0 010 1.414l-4 4a1 1 0 01-1.414-1.414L8.586 8 5.293 4.707a1 1 0 010-1.414z" 
            fill="currentColor"/>
    </svg>
  </button>

  <!-- Compteur pour démo -->
  <p class="mt-6 text-gray-400">Clics : <span x-text="count" class="text-white font-mono"></span></p>
</body>
</html>" }} />
  );
}
